import{z as o,x as s,o as A,c as D,q as r,j as n,D as a,d as B,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"做市绩效归因","description":"","frontmatter":{"title":"做市绩效归因","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-pnl-attribution.md","filePath":"quant/mm-pnl-attribution.md","lastUpdated":1791063341000}'),d={name:"quant/mm-pnl-attribution.md"};function p(u,E,m,F,C,c){const t=s("Mermaid");return A(),D("div",null,[E[2]||(E[2]=r('<h1 id="做市绩效归因" tabindex="-1">做市绩效归因 <a class="header-anchor" href="#做市绩效归因" aria-label="Permalink to &quot;做市绩效归因&quot;">​</a></h1><div class="epigraph"><p>总损益是一个混合物：不拆开，毒性亏损会被读成运气差，顺风行情会被读成能力；两种误读各自导向一种错误的参数动作。</p><footer>—— 据 Huang and Stoll, Journal of Finance, 1997；O&#39;Hara, Market Microstructure Theory, 1995 整理</footer></div><p><a href="/quant/mm-crossproduct">上一课</a>把簿扩成向量并给每个净暴露找到了出口。向量簿赚了还是亏了、赚在哪亏在哪，需要把钱拆到机制上。第一课说模型是分解器，本课把同样的分解用到损益上，并让归因回馈参数——这是「做市业务深入」里承上启下的一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>做市总 PnL 是混合物：价差捕获、存货漂移损益、逆向选择损失、费用与回扣、对冲成本、队列资本的隐性收益。不拆开有两种误读：把毒性亏损归因于「行情不好」，于是去调宽度而该收紧的是检测阈值；把顺风行情归因于「策略有效」，于是加杠杆而其实只是市场替你付了存货损益。两种误读都直接写坏参数——归因不是报表，是校准回路的一半。</p><h3 id="逐笔恒等式" tabindex="-1">逐笔恒等式 <a class="header-anchor" href="#逐笔恒等式" aria-label="Permalink to &quot;逐笔恒等式&quot;">​</a></h3><p>逐笔成交拆五个桶：成交价对当时公允价，得价差收入（\\(2D(P-M)\\)，有效价差口径）；成交后固定 \\(\\tau\\) 的中点位移，得实现价差与逆向选择（\\(2D(M_{\\tau}-M_t)\\)，口径见<a href="/quant/adverse-selection-cost">逆向选择成本度量</a>与<a href="/quant/effective-realized-spread">有效与实现价差</a>）；持有期内中点漂移，得存货损益；费率表，得回扣与费用（<a href="/quant/maker-taker">maker-taker</a> 口径）；对冲腿的价差与冲击，单列为对冲成本。概念上的处理、存货、信息三分见<a href="/quant/spread-decomposition">价差分解</a>。恒等式加总必须等于总 PnL——对不上账先查 \\(\\tau\\)、方向标志与公允价定义，再谈任何结论。</p><p><span class="marginnote">「逆向选择」翻译成大白话：和你做对手盘的人往往比你先知道消息——你挂出的单子总在坏消息落地前成交。于是「成交了」本身成了坏消息：成交后中点朝对你不利的方向走，走掉的那一段就是逆向选择损失，它和价差收入记在同一笔成交上，方向相反。</span></p><p><span class="marginnote">回扣主导的场所里，毛价差收入可以为负而净 PnL 为正：归因若不先做费用调整，「价差捕获」一栏直接把回扣误当 alpha，宽度与强度的校准会朝错误方向走。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>口径先锁死再算账：\\(\\tau\\) 一组窗口并排报（口径纪律见逆向选择度量一课）；方向标志用交易所主动被动标记优先；公允价用跨场所锚——跨品种课的锚联动在这里复用。归因做完恒等式再做条件切片：按波动体制、成交量分位、时段、对手层看各桶占比。毒性损失通常集中在少数日与少数层，全期平均会把信号抹平——切片才看得见「哪天、对谁、哪个动作」亏的钱。</p><p>数字实例：你在 \\(100.02\\) 卖出、当时中点 \\(100.00\\)，毛赚半个价差 \\(0.02\\)；若 \\(\\tau=1\\) 秒后中点涨到 \\(100.05\\)，说明你卖在了真实价值之下 \\(0.05\\)。这笔的实现收益 \\(=0.02-0.05=-0.03\\)：表面上捕获了价差，实际被逆向选择吃穿。所以看毛价差做报表、看实现价差做校准，两者的差就是对手比你聪明的那部分。</p>',12)),(A(),n(l,null,{default:a(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E9%80%90%E7%AC%94%E6%88%90%E4%BA%A4%22%5D%20--%3E%20ES%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E5%85%A5%202D(P%E2%88%92M)%22%5D%0A%20%20FILL%20--%3E%20AS%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%202D(M%CF%84%E2%88%92M)%22%5D%0A%20%20HOLD%5B%22%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%20--%3E%20INV%5B%22%E5%AD%98%E8%B4%A7%E6%8D%9F%E7%9B%8A%22%5D%0A%20%20FILL%20--%3E%20FEE%5B%22%E5%9B%9E%E6%89%A3%E4%B8%8E%E8%B4%B9%E7%94%A8%22%5D%0A%20%20HEDGE%5B%22%E5%AF%B9%E5%86%B2%E8%85%BF%E6%88%90%E4%BA%A4%22%5D%20--%3E%20HC%5B%22%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%22%5D%0A%20%20ES%20--%3E%20SUM%5B%22%E6%81%92%E7%AD%89%E5%BC%8F%E5%8A%A0%E6%80%BB%20%3D%20%E6%80%BB%20PnL%22%5D%0A%20%20AS%20--%3E%20SUM%0A%20%20INV%20--%3E%20SUM%0A%20%20FEE%20--%3E%20SUM%0A%20%20HC%20--%3E%20SUM%0A%20%20SUM%20--%3E%20SLICE%5B%22%E6%9D%A1%E4%BB%B6%E5%88%87%E7%89%87%EF%BC%9A%E4%BD%93%E5%88%B6%E3%80%81%E6%97%B6%E6%AE%B5%E3%80%81%E5%AF%B9%E6%89%8B%E5%B1%82%22%5D%0A%20%20SLICE%20--%3E%20PARAM%5B%22%E5%9B%9E%E5%86%99%E5%8F%82%E6%95%B0%EF%BC%9A%E5%AE%BD%E5%BA%A6%E3%80%81%E5%81%8F%E5%BA%A6%E3%80%81%E9%98%88%E5%80%BC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,"归因到参数的映射是闭环的另一半：价差收入持续低于模型，强度项过时，回第一课的 \\(A,\\kappa\\) 重估；逆向选择占比升高，毒性检测松了或对手分层错了，回第四、五课调阈值；存货损益方差超预算，偏度系数或限额翻译错了，回第二、六课；对冲成本占比高，对冲带太窄，回第三课放宽。每个桶都有明确的负责人与动作，这才是「归因」区别于「报表」的地方。",-1)),(A(),n(l,null,{default:a(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E4%BB%B7%E5%B7%AE%E6%94%B6%E5%85%A5%E6%8C%81%E7%BB%AD%E5%81%8F%E4%BD%8E%22%5D%20--%3E%20DA%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E5%BC%BA%E5%BA%A6%E9%A1%B9%E8%BF%87%E6%97%B6%22%5D%0A%20%20DA%20--%3E%20PA%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E9%87%8D%E4%BC%B0%20A%20%E4%B8%8E%20%CE%BA%22%5D%0A%20%20B%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E5%8D%A0%E6%AF%94%E5%8D%87%E9%AB%98%22%5D%20--%3E%20DB%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E6%AF%92%E6%80%A7%E9%98%88%E5%80%BC%E6%9D%BE%20%2F%20%E5%88%86%E5%B1%82%E9%94%99%22%5D%0A%20%20DB%20--%3E%20PB%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E6%94%B6%E7%B4%A7%E6%A3%80%E6%B5%8B%E9%98%88%E5%80%BC%22%5D%0A%20%20C%5B%22%E5%AD%98%E8%B4%A7%E6%8D%9F%E7%9B%8A%E6%96%B9%E5%B7%AE%E8%B6%85%E9%A2%84%E7%AE%97%22%5D%20--%3E%20DC%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E5%81%8F%E5%BA%A6%E6%88%96%E9%99%90%E9%A2%9D%E7%BF%BB%E8%AF%91%E9%94%99%22%5D%0A%20%20DC%20--%3E%20PC%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E8%B0%83%E5%81%8F%E5%BA%A6%E7%B3%BB%E6%95%B0%E4%B8%8E%E9%99%90%E9%A2%9D%22%5D%0A%20%20E%5B%22%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%E5%8D%A0%E6%AF%94%E5%81%8F%E9%AB%98%22%5D%20--%3E%20DE%5B%22%E8%AF%8A%E6%96%AD%EF%BC%9A%E5%AF%B9%E5%86%B2%E5%B8%A6%E5%A4%AA%E7%AA%84%22%5D%0A%20%20DE%20--%3E%20PE%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E6%94%BE%E5%AE%BD%E5%AF%B9%E5%86%B2%E5%B8%A6%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：初学者容易以为做市赚的就是「每笔价差」，实际上库存本身也在赚钱亏钱——价格整体上漂时，被动攒下的多头存货白捡收益，下漂时白亏。不把这一桶单独拆出来，行情顺风会被误读成报价能力强，接着加杠杆，反而放大下一个逆风期的存货亏损。</span></p><p>队列位置是隐性科目：每次改价丧失时间优先的机会成本不进现金账，却真实影响成交质量，见<a href="/quant/cancel-queue-position">撤单、改单与队列位置</a>与<a href="/quant/fill-probability">排队与成交概率</a>。精确入账困难，至少作为压力项单列，防止把队列资本的损耗误读成「报价不够积极」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>中点漂移里信息与存货不分：归因给出会计事实，不给因果识别——这是价差分解一课的识别边界。自身大单推动中点会低估冲击，归因窗口内要剔除或标记自己的主导时段。费前归因在回扣主导的场所误导，跨场所比较必须费用调整。停掉的策略也进归因台账，否则归因有幸存者偏差——这与研究复盘课的台账口径一致：负结果可检索，归因才完整。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>逐笔恒等式拆五桶：价差收入、逆向选择、存货损益、费用回扣、对冲成本；加总必须对上总 PnL。</li><li>口径（\\(\\tau\\)、方向、公允价）先锁死，窗口并排报。</li><li>条件切片按体制、时段、对手层做，毒性集中在少数日，平均会抹平信号。</li><li>每个桶回写到明确参数：归因是校准回路，不是报表。</li><li>队列位置作压力项单列；停掉的策略进台账防幸存者偏差。</li><li>出处：Huang and Stoll, <em>Journal of Finance</em>, 1997 与 <em>Journal of Financial Economics</em>, 1996；O&#39;Hara, <em>Market Microstructure Theory</em>, 1995。</li></ul>',6))])}const _=o(d,[["render",p]]);export{f as __pageData,_ as default};
